g; // Ej: \"Administrador\", \"Usuario\", etc.\n}\n\n@Injectable({ providedIn: 'root' })\nexport class UsuariosService {\n  private key = 'usersData';\n\n  constructor() {\n    this.inicializarAdmin();\n  }\n\n  private inicializarAdmin(): void {\n    const data = localStorage.getItem(this.key);\n    const users: Usuario[] = data ? JSON.parse(data) : [];\n\n    const existeAdmin = users.some(\n      u => u.email?.trim().toLowerCase() === 'bastian1116@hotmail.com'\n    );\n\n    if (!existeAdmin) {\n      users.push({\n        nombre: 'Bastián',\n        apellido: 'Hinojosa',\n        email: 'bastian1116@hotmail.com',\n        password: '1Duoc*!',\n        foto: 'https://randomuser.me/api/portraits/men/1.jpg',\n        perfil: 'Administrador'\n      });\n      this.setUsuarios(users);\n    }\n  }\n\n  getUsuarios(): Usuario[] {\n    const data = localStorage.getItem(this.key);\n    return data ? JSON.parse(data) : [];\n  }\n\n  setUsuarios(users: Usuario[]): void {\n    localStorage.setItem(this.key, JSON.stringify(users));\n  }\n}\n    \n\n\n\n\n\n\n\n\n\n                   \n    \n         results matching \"\"\n        \n    \n    \n        No results matching \"\"\n    \n\n"},"components/UsuariosComponent.html":{"url":"components/UsuariosComponent.html","title":"component - UsuariosComponent","body":"\n                   \n\n\n\n\n\n  Components\n  \n  UsuariosComponent\n\n\n\n        \n            Info\n        \n        \n            Source\n        \n        \n            Template\n        \n        \n            Styles\n        \n        \n            DOM Tree\n        \n\n\n\n    \n    File\n\n\n    src/app/usuarios/usuarios.component.ts\n\n\n\n\n\n    \n        Implements\n    \n    \n                OnInit\n    \n\n\n\n    Metadata\n    \n        \n\n\n\n\n\n\n\n\n\n\n\n\n            \n                selector\n                app-usuarios\n            \n\n\n\n            \n                styleUrls\n                ./usuarios.component.css\n            \n